import sys

tokens = sys.stdin.read().split()
pos = 0
m = int(tokens[pos])
pos += 1
mijozlar = {}
for _ in range(m):
    mijozlar[tokens[pos]] = (tokens[pos + 1], tokens[pos + 2])
    pos += 3
k = int(tokens[pos])
pos += 1
jami, soni = {}, {}
for _ in range(k):
    mid = tokens[pos + 1]
    jami[mid] = jami.get(mid, 0) + int(tokens[pos + 2])
    soni[mid] = soni.get(mid, 0) + 1
    pos += 3
for mid in sorted(jami, key=lambda x: (-jami[x], x)):
    ism, shahar = mijozlar[mid]
    print(f"{ism} ({shahar}): {soni[mid]} orders, {jami[mid]}")
for mid in sorted(mijozlar):
    if mid not in jami:
        print(f"{mijozlar[mid][0]} ({mijozlar[mid][1]}): no orders")

