import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int m = in.nextInt();
        Map<String, String[]> mijozlar = new TreeMap<>();
        for (int i = 0; i < m; i++) {
            String id = in.next();
            mijozlar.put(id, new String[] {in.next(), in.next()});
        }
        int k = in.nextInt();
        Map<String, Long> jami = new HashMap<>();
        Map<String, Integer> soni = new HashMap<>();
        for (int i = 0; i < k; i++) {
            in.next();
            String mijozId = in.next();
            long summa = in.nextLong();
            jami.merge(mijozId, summa, Long::sum);
            soni.merge(mijozId, 1, Integer::sum);
        }
        List<String> tartib = new ArrayList<>(jami.keySet());
        tartib.sort((a, b) -> !jami.get(a).equals(jami.get(b)) ? Long.compare(jami.get(b), jami.get(a)) : a.compareTo(b));
        for (String mid : tartib) {
            String[] mj = mijozlar.get(mid);
            System.out.println(mj[0] + " (" + mj[1] + "): " + soni.get(mid) + " orders, " + jami.get(mid));
        }
        for (Map.Entry<String, String[]> e : mijozlar.entrySet()) {
            if (!jami.containsKey(e.getKey())) {
                System.out.println(e.getValue()[0] + " (" + e.getValue()[1] + "): no orders");
            }
        }
    }
}

