#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <utility>
#include <vector>
using namespace std;

int main() {
    int m, k;
    cin >> m;
    map<string, pair<string, string>> mijozlar;
    for (int i = 0; i < m; i++) {
        string id, ism, shahar;
        cin >> id >> ism >> shahar;
        mijozlar[id] = {ism, shahar};
    }
    cin >> k;
    map<string, long long> jami;
    map<string, int> soni;
    for (int i = 0; i < k; i++) {
        string bid, mijozId;
        long long summa;
        cin >> bid >> mijozId >> summa;
        jami[mijozId] += summa;
        soni[mijozId] += 1;
    }
    vector<string> tartib;
    for (auto& p : jami) tartib.push_back(p.first);
    sort(tartib.begin(), tartib.end(), [&](const string& a, const string& b) {
        return jami[a] != jami[b] ? jami[a] > jami[b] : a < b;
    });
    for (const string& mid : tartib) {
        auto& mj = mijozlar[mid];
        cout << mj.first << " (" << mj.second << "): " << soni[mid] << " orders, " << jami[mid] << endl;
    }
    for (const auto& p : mijozlar) {
        if (!jami.count(p.first)) cout << p.second.first << " (" << p.second.second << "): no orders" << endl;
    }
    return 0;
}
